const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const { JSDOM } = require('happy-dom');

// ---------------------------------------------------------------------------
// Background
// ---------------------------------------------------------------------------

Given('the TodoMVC app is loaded', function () {
  // Already loaded by Before hook in world.js.
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getTodos(doc) {
  return Array.from(doc.querySelectorAll('.todo-list li'));
}

function findTodo(doc, title) {
  const items = getTodos(doc);
  return items.find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
}

function assertTodoExists(doc, title) {
  const todo = findTodo(doc, title);
  if (!todo) throw new Error(`Expected todo "${title}" to exist in the list`);
  return todo;
}

function assertTodoNotExists(doc, title) {
  const todo = findTodo(doc, title);
  if (todo) throw new Error(`Expected todo "${title}" to NOT exist in the list`);
}

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected empty todo list');
});

Given(/^the todo list has the item "([^"]+)"$/, function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given(/^the todo list has the items "([^"]+)" and "([^"]+)"$/, function (title1, title2) {
  const input = this.document.querySelector('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.value = title2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given(/^the todo list has the completed item "([^"]+)"$/, function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  const todo = findTodo(this.document, title);
  if (todo) {
    const toggle = todo.querySelector('.toggle');
    if (toggle) { toggle.checked = true; toggle.dispatchEvent(new this.window.Event('change', { bubbles: true })); }
  }
});

Given(/^the todo list has the completed item "([^"]+)" and the active item "([^"]+)"$/, function (completedTitle, activeTitle) {
  const input = this.document.querySelector('.new-todo');
  input.value = completedTitle;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  const todo = findTodo(this.document, completedTitle);
  if (todo) {
    const toggle = todo.querySelector('.toggle');
    if (toggle) { toggle.checked = true; toggle.dispatchEvent(new this.window.Event('change', { bubbles: true })); }
  }
  input.value = activeTitle;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('the todo list has only active items', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = 'Buy groceries';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.value = 'Walk the dog';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given(/^the URL hash is "([^"]+)"$/, function (hash) {
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Given('localStorage has the following todos', function (table) {
  const todos = table.hashes().map(row => ({
    id: row.id,
    title: row.title,
    completed: row.completed === 'true',
  }));
  this.localStorage.setItem('todos-javascript', JSON.stringify(todos));
});

Given(/^I am viewing the active filter$/, function () {
  this.navigate('#/active');
});

Given(/^I am viewing the completed filter$/, function () {
  this.navigate('#/completed');
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When(/^I type "([^"]*)" into the new-todo input and press Enter$/, function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I click the toggle checkbox for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const toggle = todo.querySelector('.toggle');
  if (!toggle) throw new Error(`No toggle checkbox found for "${title}"`);
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When(/^I click the "([^"]+)" toggle$/, function (label) {
  const toggleAll = this.document.getElementById('toggle-all');
  if (!toggleAll) throw new Error('No toggle-all checkbox found');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I complete all todos individually', function () {
  const todos = getTodos(this.document);
  for (const li of todos) {
    const toggle = li.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.checked = true;
      toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  }
});

When(/^I click the "Clear completed" button$/, function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button found');
  btn.click();
});

When(/^I click the destroy button for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const btn = todo.querySelector('.destroy');
  if (!btn) throw new Error(`No destroy button for "${title}"`);
  btn.click();
});

When(/^I double-click the label for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const label = todo.querySelector('label');
  if (!label) throw new Error(`No label for "${title}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and press Enter$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and tab away$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and press Escape$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I navigate to the "([^"]+)" route$/, function (hash) {
  this.navigate(hash);
});

When(/^I click the "([^"]+)" filter link$/, function (name) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === name);
  if (!link) throw new Error(`No filter link "${name}" found`);
  link.click();
});

When('I reload the app', function () {
  // Dispose and reload — simulate page reload by creating a fresh window/app.
  // We keep current localStorage (which persists across page reloads in a real browser).
  const stored = {};
  for (let i = 0; i < this.localStorage.length; i++) {
    const key = this.localStorage.key(i);
    stored[key] = this.localStorage.getItem(key);
  }
  // Dispose
  this.disposeApp();
  // Reload
  this.loadApp();
  // Restore localStorage
  for (const [key, val] of Object.entries(stored)) {
    this.localStorage.setItem(key, val);
  }
  // Dispatch hashchange for current hash
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When('I complete the todo {string}', function (title) {
  const todo = assertTodoExists(this.document, title);
  const toggle = todo.querySelector('.toggle');
  if (!toggle) throw new Error(`No toggle checkbox for "${title}"`);
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

// ---------------------------------------------------------------------------
// Then steps
// ---------------------------------------------------------------------------

Then(/^the todo "([^"]+)" appears in the list$/, function (title) {
  assertTodoExists(this.document, title);
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

Then('the todo list remains empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then(/^the todo "([^"]+)" has the class "completed"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  assert.ok(todo.classList.contains('completed'), `Expected "${title}" to have class "completed"`);
});

Then(/^the todo "([^"]+)" does not have the class "completed"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  assert.ok(!todo.classList.contains('completed'), `Expected "${title}" to NOT have class "completed"`);
});

Then('all todos have the class {string}', function (className) {
  const todos = getTodos(this.document);
  assert.ok(todos.length > 0, 'Expected at least one todo');
  todos.forEach(li => {
    assert.ok(li.classList.contains(className), 'Expected all todos to have class "' + className + '"');
  });
});

Then(/^the "Mark all as complete" checkbox is checked$/, function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'Expected toggle-all checkbox to exist');
  assert.ok(toggleAll.checked, 'Expected toggle-all checkbox to be checked');
});

Then(/^the todo list contains only "([^"]+)"$/, function (title) {
  const todos = getTodos(this.document);
  assert.strictEqual(todos.length, 1, 'Expected exactly one todo');
  const label = todos[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title, `Expected todo "${title}"`);
});

Then(/^the "Clear completed" button is not visible$/, function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) return; // not present
  const style = this.window.getComputedStyle(btn);
  if (style.display === 'none' || style.visibility === 'hidden') return;
  // Also check hidden attribute
  if (btn.hasAttribute('hidden')) return;
  // Check if the parent footer is hidden
  const footer = this.document.querySelector('.footer');
  if (footer && (footer.style.display === 'none' || footer.classList.contains('hidden'))) return;
  throw new Error('Expected "Clear completed" button to be not visible');
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  if (!main) return; // not present
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none' || style.visibility === 'hidden') return;
  if (main.hasAttribute('hidden')) return;
  throw new Error('Expected main section to be hidden');
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer) return; // not present
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none' || style.visibility === 'hidden') return;
  if (footer.hasAttribute('hidden')) return;
  throw new Error('Expected footer section to be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Expected main section to exist');
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none') throw new Error('Expected main section to be visible');
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Expected footer section to exist');
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none') throw new Error('Expected footer section to be visible');
});

Then(/^the todo-count shows "([^"]+)"$/, function (text) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'Expected .todo-count element');
  assert.strictEqual(el.textContent.trim(), text, 'Expected todo-count to show "' + text + '"');
});

Then(/^the todo has the class "editing"$/, function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert.ok(editing, 'Expected a todo in editing mode');
});

Then(/^the edit input contains "([^"]+)"$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert.ok(editing, 'Expected a todo in editing mode');
  const editInput = editing.querySelector('.edit');
  assert.ok(editInput, 'Expected an edit input');
  assert.strictEqual(editInput.value, text, 'Expected edit input to contain "' + text + '"');
});

Then(/^the todo does not have the class "editing"$/, function () {
  const editing = this.document.querySelectorAll('.todo-list li.editing');
  assert.strictEqual(editing.length, 0, 'Expected no todos in editing mode');
});

Then(/^the todo list shows "([^"]+)" and "([^"]+)"$/, function (title1, title2) {
  const todos = getTodos(this.document);
  const visibleTitles = todos.map(li => {
    // Respect visibility: a hidden li (display:none) is not shown
    if (li.style.display === 'none') return null;
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : null;
  }).filter(Boolean);
  assert.ok(visibleTitles.includes(title1), `Expected "${title1}" to be shown`);
  assert.ok(visibleTitles.includes(title2), `Expected "${title2}" to be shown`);
});

Then(/^the todo list shows only "([^"]+)"$/, function (title) {
  const todos = getTodos(this.document);
  const visibleTitles = todos.map(li => {
    if (li.style.display === 'none') return null;
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : null;
  }).filter(Boolean);
  assert.strictEqual(visibleTitles.length, 1, 'Expected exactly one visible todo');
  assert.strictEqual(visibleTitles[0], title, `Expected visible todo to be "${title}"`);
});

Then(/^the "([^"]+)" filter link has the class "selected"$/, function (name) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === name);
  assert.ok(link, `No filter link "${name}" found`);
  assert.ok(link.classList.contains('selected'), `Expected "${name}" link to have class "selected"`);
});

Then(/^the "([^"]+)" filter link does not have the class "selected"$/, function (name) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === name);
  if (!link) return; // if it doesn't exist, it can't have selected
  assert.ok(!link.classList.contains('selected'), `Expected "${name}" link to NOT have class "selected"`);
});

// ---------------------------------------------------------------------------
// Persistence steps
// ---------------------------------------------------------------------------

Then(/^the localStorage key "([^"]+)" contains an item with title "([^"]+)"$/, function (key, title) {
  const data = JSON.parse(this.localStorage.getItem(key));
  assert.ok(Array.isArray(data), `Expected localStorage key "${key}" to contain an array`);
  const item = data.find(t => t.title === title);
  assert.ok(item, `Expected an item with title "${title}" in localStorage`);
});

Then(/^the localStorage item for "([^"]+)" has completed set to true$/, function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-javascript'));
  assert.ok(Array.isArray(data), 'Expected todos in localStorage');
  const item = data.find(t => t.title === title);
  assert.ok(item, `Expected item "${title}" in localStorage`);
  assert.strictEqual(item.completed, true, `Expected "${title}" completed to be true`);
});

Then(/^the localStorage key "([^"]+)" has no items$/, function (key) {
  const data = JSON.parse(this.localStorage.getItem(key));
  assert.ok(Array.isArray(data), `Expected localStorage key "${key}" to contain an array`);
  assert.strictEqual(data.length, 0, `Expected localStorage key "${key}" to have no items`);
});

