/**
 * @planks("the TodoMVC app is loaded")
 * @planks("the todo list is empty")
 * @planks("I type {string} into the new-todo input and press Enter")
 * @planks("the todo {string} appears in the list")
 * @planks("the new-todo input is cleared")
 * @planks("the todo list remains empty")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("the todo {string} has the class {string}")
 * @planks("the todo {string} does not have the class {string}")
 * @planks("I click the {string} toggle")
 * @planks("all todos have the class {string}")
 * @planks("I complete all todos individually")
 * @planks("the {string} checkbox is checked")
 * @planks("I click the \"Clear completed\" button")
 * @planks("the todo list contains only {string}")
 * @planks("the \"Clear completed\" button is not visible")
 * @planks("I click the destroy button for {string}")
 * @planks("the main section is hidden")
 * @planks("the footer section is hidden")
 * @planks("the main section is visible")
 * @planks("the footer section is visible")
 * @planks("the todo-count shows {string}")
 * @planks("I double-click the label for {string}")
 * @planks("the todo has the class {string}")
 * @planks("the edit input contains {string}")
 * @planks("I change the edit input to {string} and press Enter")
 * @planks("I change the edit input to {string} and tab away")
 * @planks("I change the edit input to {string} and press Escape")
 * @planks("I clear the edit input and press Enter")
 * @planks("the todo does not have the class {string}")
 * @planks("the URL hash is {string}")
 * @planks("the todo list shows {string} and {string}")
 * @planks("the todo list shows only {string}")
 * @planks("I navigate to the {string} route")
 * @planks("the {string} filter link has the class {string}")
 * @planks("the {string} filter link does not have the class {string}")
 * @planks("I click the {string} filter link")
 * @planks("I am viewing the active filter")
 * @planks("I am viewing the completed filter")
 * @planks("I complete the todo {string}")
 * @planks("the localStorage key {string} contains an item with title {string}")
 * @planks("localStorage has the following todos")
 * @planks("I reload the app")
 * @planks("the localStorage item for {string} has completed set to true")
 * @planks("the localStorage key {string} has no items")
 * @planks("Persist todos to localStorage")
 * @planks("Restore todos from localStorage on load")
 * @planks("Persist completed state to localStorage")
 * @planks("Persist deleted todos — removed from localStorage")
 * @planks("Persist filter state across reload")
 * @planks("Do not persist editing state")
 */
(function () {
  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';
  var editingId = null;

  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var todoCount = document.querySelector('.todo-count');
  var filters = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      if (data) { todos = JSON.parse(data); }
    } catch (e) { todos = []; }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilter() {
    var hash = location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function filteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function activeCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function completedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  function render() {
    var items = filteredTodos();
    var html = '';
    for (var i = 0; i < items.length; i++) {
      var t = items[i];
      var liClass = '';
      if (t.completed) liClass += 'completed';
      if (t.id === editingId) {
        if (liClass) liClass += ' ';
        liClass += 'editing';
      }
      html += '<li class="' + liClass + '" data-id="' + t.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(t.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(t.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    var count = activeCount();
    var word = count === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';

    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }

    toggleAll.checked = todos.length > 0 && completedCount() === todos.length;

    if (completedCount() === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    var currentFilter = getFilter();
    for (var j = 0; j < filters.length; j++) {
      var a = filters[j];
      var href = a.getAttribute('href');
      if ((href === '#/' && currentFilter === 'all') ||
          (href === '#/active' && currentFilter === 'active') ||
          (href === '#/completed' && currentFilter === 'completed')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    var id = Date.now() + Math.random();
    todos.push({ id: id, title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.length > 0 && completedCount() === todos.length;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allCompleted;
    }
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    editingId = null;
    render();
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  // --- Event delegation ---

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('change', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    }
  });

